// Robin keeps a hidden goodwill score: insult -2, apology +1, gift +1; warm iff score > 0.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apology" || action === "gift") score += 1;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

// Robin starts cold if the first action is not an apology, and turns cold forever after any pair of consecutive insults; gifts do nothing.
function visible(actions) {
  if (actions.length === 0 || actions[0] !== "apology") {
    return { mood: "cold" };
  }
  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: "warm" };
}

// Robin counts every apology or gift as +1 and every insult as -1; warm iff the net count is positive.
