// Robin warms if there is an apology, no adjacent insults, and no more than two gifts total.
function visible(actions) {
  let hasApology = false;
  let gifts = 0;
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "apologise") hasApology = true;
    if (actions[i] === "gift") gifts++;
    if (i > 0 && actions[i - 1] === "insult" && actions[i] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: hasApology && gifts <= 2 ? "warm" : "cold" };
}

// Robin warms with an apology, no adjacent insults, and not ending on an insult.
function visible(actions) {
  let hasApology = false;
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "apologise") hasApology = true;
    if (i > 0 && actions[i - 1] === "insult" && actions[i] === "insult") {
      return { mood: "cold" };
    }
  }
  const last = actions[actions.length - 1];
  return { mood: hasApology && last !== "insult" ? "warm" : "cold" };
}

// Robin warms either with an apology and no adjacent insults unless both ends are insults, or with only gifts and no insults.
function visible(actions) {
  let hasApology = false;
  let hasInsult = false;
  let hasGift = false;

  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "apologise") hasApology = true;
    if (actions[i] === "insult") hasInsult = true;
    if (actions[i] === "gift") hasGift = true;
    if (i > 0 && actions[i - 1] === "insult" && actions[i] === "insult") {
      return { mood: "cold" };
    }
  }

  const first = actions[0];
  const last = actions[actions.length - 1];
  const apologyRule = hasApology && !(first === "insult" && last === "insult");
  const giftOnlyRule = !hasInsult && hasGift;

  return { mood: apologyRule || giftOnlyRule ? "warm" : "cold" };
}

